begin;
create table private.sale_contract_template_versions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),template_id uuid not null,version integer not null check(version>0),title text not null,body text not null,status text not null default 'draft' check(status in ('draft','approved','retired')),approval_version integer not null default 1 check(approval_version>0),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),approved_at timestamptz,unique(company_id,template_id,version),unique(company_id,id),check(length(title) between 2 and 160 and title !~ '[[:cntrl:]]'),check(length(body) between 2 and 12000 and translate(body,E'\n\r\t','') !~ '[[:cntrl:]]'),check(status<>'approved' or approved_at is not null));
create unique index sale_contract_template_current on private.sale_contract_template_versions(company_id,template_id) where status='approved';
create index sale_contract_template_actor on private.sale_contract_template_versions(created_by);
create table private.sale_contract_drafts(id uuid primary key default gen_random_uuid(),company_id uuid not null,deal_id uuid not null,version integer not null check(version>0),offer_id uuid not null,template_version_id uuid not null,snapshot jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),foreign key(company_id,deal_id) references public.deals(company_id,id),foreign key(company_id,offer_id) references public.offers(company_id,id),foreign key(company_id,template_version_id) references private.sale_contract_template_versions(company_id,id),unique(company_id,deal_id,version),unique(company_id,offer_id,template_version_id));
create index sale_contract_draft_actor on private.sale_contract_drafts(created_by);
create index sale_contract_draft_template on private.sale_contract_drafts(company_id,template_version_id);
create table private.sale_contract_audit(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),actor_user_id uuid not null references auth.users(id),request_id uuid not null,payload jsonb not null,receipt jsonb not null,created_at timestamptz not null default clock_timestamp(),unique(actor_user_id,request_id));
create index sale_contract_audit_company on private.sale_contract_audit(company_id,created_at);
alter table private.sale_contract_template_versions enable row level security;
alter table private.sale_contract_drafts enable row level security;
alter table private.sale_contract_audit enable row level security;
revoke all on private.sale_contract_template_versions,private.sale_contract_drafts,private.sale_contract_audit from public,anon,authenticated,service_role;
create function private.sale_contract_immutable() returns trigger language plpgsql set search_path='' as $$begin
 if tg_table_name<>'sale_contract_template_versions' or tg_op='DELETE' then raise exception 'Immutable contract source' using errcode='55000';end if;
 if (to_jsonb(new)-array['status','approval_version','approved_at']) is distinct from(to_jsonb(old)-array['status','approval_version','approved_at']) or new.approval_version<>old.approval_version+1 or old.status='retired' or new.status not in ('approved','retired') or old.status=new.status or(old.status='approved' and new.approved_at is distinct from old.approved_at) then raise exception 'Immutable contract source' using errcode='55000';end if;return new;end$$;
create trigger sale_contract_template_immutable before update or delete on private.sale_contract_template_versions for each row execute function private.sale_contract_immutable();
create trigger sale_contract_draft_immutable before update or delete on private.sale_contract_drafts for each row execute function private.sale_contract_immutable();
create trigger sale_contract_audit_immutable before update or delete on private.sale_contract_audit for each row execute function private.sale_contract_immutable();
create function private.sale_contract_access(c uuid,template_write boolean default false) returns table(actor uuid,actor_role text) language plpgsql set search_path='' as $$declare a uuid;r text;begin select x.actor,x.actor_role into a,r from private.customer_contact_access(c,false)x;if r not in ('owner','admin','finance') or(template_write and r='finance') then raise exception 'Private contract access denied' using errcode='42501';end if;return query select a,r;end$$;
create function private.sale_contract_template_json(t private.sale_contract_template_versions) returns jsonb language sql set search_path='' as $$select jsonb_build_object('id',t.id,'companyId',t.company_id,'templateId',t.template_id,'version',t.version,'title',t.title,'body',t.body,'status',t.status,'approvalVersion',t.approval_version,'createdAt',t.created_at,'approvedAt',t.approved_at,'createdBy',t.created_by);$$;
create function private.sale_contract_draft_json(d private.sale_contract_drafts) returns jsonb language sql set search_path='' as $$select d.snapshot||jsonb_build_object('id',d.id,'companyId',d.company_id,'dealId',d.deal_id,'version',d.version,'offerId',d.offer_id,'createdAt',d.created_at,'createdBy',d.created_by);$$;
revoke all on function private.sale_contract_immutable(),private.sale_contract_access(uuid,boolean),private.sale_contract_template_json(private.sale_contract_template_versions),private.sale_contract_draft_json(private.sale_contract_drafts) from public,anon,authenticated,service_role;
commit;
